//      \u51FA\u73B0\u4E00\u6B21\u65AD\u70B9\uFF08\u8868\u73B0\u4E3A shake \u6548\u679C\u89C4\u5F8B\u6027\u6296\u52A8\uFF09\uFF0C\u4E14\u4E0E\u7D27\u90BB\u7684 cos(time) \u76F8\u4F4D\u4E0D\u4E00\u81F4\uFF1B
//   2. circular_text.frag: (atan2(y,x) + M_PI) / M_PI_2 \u2014\u2014 \u5206\u5B50\u57DF\u4E3A [0,2\u03C0]\uFF0C
